            ILendingPool(POOL).borrow(USDT, finalBorrowAmount, 2, 0, address(this));

            console.log("collateralAmount: %s", balanceBeforeLIDOWST);
            console.log("debtRepayAmount: %s", calcBorrowUSDT);

